def rays(I,r,c):
    h,w=len(I),len(I[0])
    def run(dr,dc):
        n=0; rr,cc=r+dr,c+dc
        while 0<=rr<h and 0<=cc<w and I[rr][cc]==0: n+=1; rr+=dr; cc+=dc
        return n
    return (run(-1,0),run(1,0),run(0,-1),run(0,1))
