        for c in range(w):
            if I[r][c]==0 and O[r][c]!=0:
                covered=[(v,rays(I,r,c)) for (rr,cc,v) in cs if rr==r or cc==c]
                if len(covered)>1:
                    win=O[r][c]; wins=[i for i,(v,_) in enumerate(covered) if v==win]
                    # note winners equal values here since distinct colors
                    print('  cell',(r,c),'winner color',win,'covers with runs',covered,'winner-index',wins)

