G=load()

def solve(I):
    h,w=len(I),len(I[0])
    # find centers: cells whose color != 0 and not part of any plus-arm-of-3s? 
    # simpler: a center is a non-zero cell such that its 4 orthogonal neighbors are all 3 (or oob).
    cen=[]
    for r in range(h):
        for c in range(w):
            v=I[r][c]
            if v==0 or v==3: continue
            nb=[(r-1,c),(r+1,c),(r,c-1),(r,c+1)]
            if all(not(0<=a<h and 0<=b<w) or I[a][b]==3 for a,b in nb):
                cen.append((r,c,v))
    out=[row[:] for row in I]
    # process in scan order; each center paints row&col with its color EXCEPT keep original nonzero cells,
    # and STOP extending when reaching a cell already painted by another center (don't overwrite).
    for (r,c,v) in sorted(cen):
        def paint(rr,cc,dr,dc):
            while True:
                rr+=dr; cc+=dc
                if not(0<=rr<h and 0<=cc<w): break
                cur=out[rr][cc]
                if cur!=0: break   # blocked by anything (orig 3, painted cell, arm)
                out[rr][cc]=v
        paint(r,c,-1,0); paint(r,c,1,0); paint(r,c,0,-1); paint(r,c,0,1)
    return out

for n in ['1','2','3','4']:
    I=G[f'Demo pair {n} input']; O=G[f'Demo pair {n} output']
    P=solve(I)
    print(n, 'MATCH' if P==O else 'MISMATCH')
    if P!=O:
