def solve(I):
    h,w=len(I),len(I[0])
    cen=[(r,c,I[r][c]) for r in range(h) for c in range(w) if I[r][c] not in (0,3)]
    out=[row[:] for row in I]
    # paint only cells that will be "owned" by exactly one line (no crossing ambiguity),
    # plus crossings where vertical wins: compute ownership first, then apply.
    cover=[]  # (r,c,color,vert)
    for r,c,v in cen:
        for rr in range(h):
            if rr!=r and I[rr][c]==0: cover.append((rr,c,v,True))
        for cc in range(w):
            if cc!=c and I[r][cc]==0: cover.append((r,cc,v,False))
    # assign: if a cell covered twice with different orientation -> vertical wins
    owner={}
    for r,c,v,vert in cover:
        key=(r,c)
        cand=owner.get(key,[])
        if len(cand)>=2 and vert not in [x[3] for x in cand]:
            # vertical overrides horizontal
            pass
        owner.setdefault(key,[]).append((v,vert))
    for (r,c),lst in owner.items():
        lst=sorted(lst,key=lambda t:(not t[1],t[0]))  # vertical first, larger color second
        if len(lst)==1:
            out[r][c]=lst[0][0]
    return out

