    mk=mklist(I); mset={(r,c) for r,c,_ in mk}
    out=[row[:] for row in I]; hset=set(); vset=set()
    # horizontal first
    for mr,mc,cv in sorted(mk):
        for sgn in (1,-1):
            cc=mc+sgn
            while 0<=cc<W and I[mr][cc] in (0,3):
                hset.add((mr,cc)); out[mr][cc]=cv; cc+=sgn
    for mr,mc,cv in sorted(mk):
        for sgn in (1,-1):
            rr=mr+sgn
            while 0<=rr<H and I[rr][mc] in (0,3):
                vset.add((rr,mc))
                if vert_over_h and (rr,mc) in hset: continue
                out[rr][mc]=cv
                rr+=sgn
    return out
